create or replace TABLE KFL_PRODUCTION.DBP_MSI_DATA.COS_BONUSKAUF_TAG_SUM_2 (
	MANDANT_ID NUMBER(38,0) NOT NULL COMMENT 'Mandant_2 im DWH.',
	BONUSKAUF_ID VARCHAR(20) NOT NULL COMMENT 'Eindeutige ID einer Bonuskaufaktion.',
	DAT DATE NOT NULL COMMENT 'Datum im Format JJJJ-MM_2-TT. Dieses Datum gibt an, wann der Coupon aktiviert oder eingelöst wurde. Es wird aus dat_update in der Tabelle cos_bonuskauf_kunde_zu_2 (berechnet Aktivierungen und Einlösungen) und bon_dat aus den Bondaten in der Tabelle ods_promotion_2 abgeleitet. Im Falle einer eingelösten Coupon wird das Einlösungsdatum angezeigt, andernfalls das Aktivierungsdatum.',
	KAMPAGNEN_ID_LISTE_TXT VARCHAR(2000) COMMENT 'Komma-separierte Textliste von Kampagnen-IDs, die einer bestimmten bonuskauf_id zugeordnet sind.',
	COUPON_TYP_NAME VARCHAR(20) NOT NULL DEFAULT 'Coupon' COMMENT 'Beschreibt um welchen Coupontyp es sich handelt: Partner, Marktplatz, SMP, Coupon.',
	AKTION_TYP_NAME VARCHAR(20) NOT NULL DEFAULT 'Normal' COMMENT 'Beschreibt um welchen Aktionstyp es sich handelt: Gamification, Checkout, Kaufbar, Reco, Normal.',
	ANZ_ZIELGRUPPENGROESSE NUMBER(38,0) COMMENT 'Gibt die Zielgruppengröße des Coupons an.',
	KANAL_LISTE_TXT VARCHAR(256) COMMENT 'Komma-separierte Textliste der Kommunikationskanäle, über die der Coupon bespielt wurde. Gilt aktuell nur für Partnercoupons. DBP_DATA.COS_BONUSKAUF.BONUSKAUF_PARTNER_FG = 1: App, Web, SSC (Self Service Cockpit), Marktplatz, Kampagne. Mehrfachauswahl ist möglich.',
	ANZ_PUNKTE_COUPON_BENOETIGT NUMBER(38,0) COMMENT 'Anzahl der Punkte die eingelöst werden müssen (erwerben) um den Coupon verwenden zu können.',
	ANZ_AKTIVIERUNGEN_KAUFBAR NUMBER(38,0) COMMENT 'Gibt die Anzahl der Aktivierungen von kaufbaren Coupons wieder.',
	ANZ_AKTIVIERUNGEN_NICHT_KAUFBAR NUMBER(38,0) COMMENT 'Gibt die Anzahl der Aktivierungen von nicht-kaufbaren Coupons wieder.',
	ANZ_GESAMT_AKTIVIERUNGEN NUMBER(38,0) COMMENT 'Gesamtanzahl der Aktivierungen.',
	RATE_AKTIVIERUNGSQUOTE NUMBER(38,5) COMMENT 'Berechnet sich aus der Gesamtanzahl der Aktivierungen / Zielgruppengroesse.',
	ANZ_EINLOESUNGEN_KAUFBAR NUMBER(38,0) COMMENT 'Gibt die Anzahl der Einloesungen von kaufbaren Coupons wieder.',
	ANZ_EINLOESUNGEN_NICHT_KAUFBAR NUMBER(38,0) COMMENT 'Gibt die Anzahl der Einloesungen von nicht-kaufbaren Coupons wieder.',
	ANZ_GESAMT_EINLOESUNGEN NUMBER(38,0) COMMENT 'Gesamtanzahl der Einloesungen.',
	RATE_EINLOESEQUOTE NUMBER(38,5) COMMENT 'Berechnet sich aus den Gesamteinloesungen / Gesamtaktivierungen.',
	ANZ_GESAMT_PUNKTE_EINLOESUNGEN NUMBER(38,0) COMMENT 'Gesamtanzahl der eingelösten Punkte. Berechnet sich aus Anzahl Punkte Coupon benötigt * Anzahl Gesamteinloesungen.',
	ANZ_UNIQUE_KUNDEN NUMBER(38,0) COMMENT 'Anzahl der eindeutigen CRM-Kunden-IDs. Da eine_2 bonuskauf_id mehrere Kampagnen besitzen kann, zählen hier die eindeutigen crm_kunden_ids im Gültigkeitszeitraum des Coupons.',
	BETRAG_BONUSKAUF_UMSATZ_BRUTTO NUMBER(38,4) COMMENT 'Der Bruttoumsatz der durch den Coupon generiert wurde.',
	BETRAG_BONUSKAUF_UMSATZ_BRUTTO_KONZ NUMBER(38,4) COMMENT 'Der Bruttoumsatz der durch den Coupon generiert wurde, in Konzernwaehrung zum Tageskurs.',
	BETRAG_BONUSKAUF_UMSATZ_NETTO NUMBER(38,4) COMMENT 'Der Nettoumsatz der durch den Coupon generiert wurde.',
	BETRAG_BONUSKAUF_UMSATZ_NETTO_KONZ NUMBER(38,4) COMMENT 'Der Nettoumsatz der durch den Coupon generiert wurde, in Konzernwaehrung zum Tageskurs.',
	MENGE_BONUSKAUF_BME NUMBER(38,3) COMMENT 'Die Abverkaufsmenge die durch den Coupon generiert wurde. Es kann in Stück oder bei Gewichtsartikeln in KG sein.',
	TD_UPDATE TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	TD_INSERT TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	constraint PK_COS_BONUSKAUF_TAG_SUM primary key (MANDANT_ID, BONUSKAUF_ID, DAT)
)COMMENT='Couponaggregationstabelle zur Optimierung der Performance in EK Kunde'
;